// The game ad as colour ASCII art (200x150 characters, see art/), with the
// chimney fire, its smoke and the fires on the horizon animated. Used as the
// background of the start screen and of the intro's title scene.
// Frame data comes from adart-data.js (window.AdArtData, generated by art/tools).
(function () {
    const FPS = 12;
    const BOOST = 1.5; // thin glyphs on black look darker than the source pixels
    let D = null, palette = null;

    function init() {
        if (D || !window.AdArtData) return !!D;
        D = window.AdArtData;
        // 12-bit colours -> brightened CSS colours, cached
        palette = new Map();
        return true;
    }
    function css(hex3) {
        let c = palette.get(hex3);
        if (!c) {
            const v = (i) => Math.min(255, Math.round(parseInt(hex3[i], 16) * 17 * BOOST));
            c = `rgb(${v(0)},${v(1)},${v(2)})`;
            palette.set(hex3, c);
        }
        return c;
    }

    // Fit the art inside w x h, keeping its 1:2 character cells.
    function layout(w, h) {
        const ch = Math.min(h / D.rows, (w * 2) / D.cols);
        const cw = ch / 2;
        return { cw, ch, ox: Math.round((w - cw * D.cols) / 2), oy: Math.round((h - ch * D.rows) / 2) };
    }

    // The static picture is drawn once per size into an offscreen canvas.
    let cache = null;
    function staticCanvas(w, h, dpr) {
        if (cache && cache.w === w && cache.h === h && cache.dpr === dpr) return cache;
        const L = layout(w, h);
        const c = document.createElement('canvas');
        c.width = Math.round(w * dpr); c.height = Math.round(h * dpr);
        const g = c.getContext('2d');
        g.scale(dpr, dpr);
        g.fillStyle = '#000'; g.fillRect(0, 0, w, h);
        // the portrait picture leaves the sides of a wide screen empty: fill them
        // with a dark, blurred copy of it, cut to cover the whole screen
        if (L.ox > 4) {
            const tiny = document.createElement('canvas');
            tiny.width = D.cols; tiny.height = D.rows * 2;
            const tg = tiny.getContext('2d');
            for (let y = 0; y < D.rows; y++) {
                for (let x = 0; x < D.cols; x++) {
                    tg.fillStyle = css(D.staticColors[y].substr(x * 3, 3));
                    tg.fillRect(x, y * 2, 1, 2);
                }
            }
            const s = w / tiny.width;
            g.save();
            g.filter = 'blur(10px) brightness(0.35)';
            g.drawImage(tiny, 0, (h - tiny.height * s) / 2, w, tiny.height * s);
            g.restore();
            g.fillStyle = '#000'; g.fillRect(L.ox, L.oy, L.cw * D.cols, L.ch * D.rows);
        }
        g.font = `${L.ch}px ui-monospace, Menlo, Consolas, monospace`;
        g.textBaseline = 'top';
        for (let y = 0; y < D.rows; y++) {
            const line = D.static[y], cols = D.staticColors[y];
            for (let x = 0; x < D.cols; x++) {
                const chr = line[x];
                if (chr === ' ') continue;
                g.fillStyle = css(cols.substr(x * 3, 3));
                g.fillText(chr, L.ox + x * L.cw, L.oy + y * L.ch, L.cw);
            }
        }
        cache = { w, h, dpr, c, L };
        return cache;
    }

    // Draw the picture at time t (seconds) into ctx, covering 0,0..w,h.
    function draw(ctx, w, h, t) {
        if (!init()) { ctx.fillStyle = '#000'; ctx.fillRect(0, 0, w, h); return; }
        const dpr = ctx.getTransform().a || 1;
        const S = staticCanvas(w, h, dpr);
        const L = S.L;
        ctx.drawImage(S.c, 0, 0, w, h);
        // a rAF timestamp can be a little older than the start time, so t may be < 0
        const f = ((Math.floor(t * FPS) % D.frames) + D.frames) % D.frames;
        const chars = D.chars[f], colors = D.colors[f];
        ctx.font = `${L.ch}px ui-monospace, Menlo, Consolas, monospace`;
        ctx.textBaseline = 'top';
        ctx.textAlign = 'left';
        for (let k = 0; k < D.cells.length; k++) {
            const idx = D.cells[k];
            const x = L.ox + (idx % D.cols) * L.cw, y = L.oy + Math.floor(idx / D.cols) * L.ch;
            ctx.fillStyle = '#000';
            ctx.fillRect(x, y, L.cw + 0.5, L.ch + 0.5);
            const chr = chars[k];
            if (chr === ' ') continue;
            ctx.fillStyle = css(colors.substr(k * 3, 3));
            ctx.fillText(chr, x, y, L.cw);
        }
    }

    // A self-running background canvas inside container, under its overlays.
    function mount(container, zIndex) {
        const canvas = document.createElement('canvas');
        Object.assign(canvas.style, { position: 'absolute', left: 0, top: 0, width: '100%', height: '100%', zIndex });
        container.appendChild(canvas);
        const ctx = canvas.getContext('2d');
        const t0 = performance.now();
        let running = true;
        (function frame(now) {
            if (!running) return;
            const w = container.clientWidth, h = container.clientHeight, dpr = window.devicePixelRatio || 1;
            if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
                canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
            }
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            draw(ctx, w, h, (now - t0) / 1000);
            requestAnimationFrame(frame);
        })(t0);
        return () => { running = false; canvas.remove(); };
    }

    window.AdArt = { draw, mount };
})();
